#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Provisions the accounts, projects and credentials the build needs (#194).
# Values that are safe to publish go to scripts/provisioned.env, which is
# committed for the workers and CI to read. Secret values go only to Secret
# Manager, EAS or GitHub secrets, never to that file or the terminal.
#
#   scripts/provision.sh            every stage not done yet, in order
#   scripts/provision.sh <stage>    one stage, done or not (re-runs are safe)
#   scripts/provision.sh --list     the stages, with a tick beside those done

# id|title|keys the stage reads, which earlier stages save
STAGES=(
  "preflight|Before we start: tools and sign-ins|"
  "gcp-staging-project|Google Cloud: the staging project|GCP_PROJECT_NUMBER_PROD"
  "gcp-apis|Google Cloud: the APIs|GCP_PROJECT_STAGING"
  "gcp-budgets|Google Cloud: billing budgets|GCP_PROJECT_STAGING DONE_GCP_APIS"
  "gcp-service-accounts|Google Cloud: service accounts and roles|GCP_PROJECT_STAGING DONE_GCP_APIS"
  "gcp-wif|Google Cloud: CI's sign-in by Workload Identity Federation|GCP_PROJECT_STAGING GCP_PROJECT_NUMBER_STAGING GCP_PROJECT_NUMBER_PROD GCP_DEPLOY_SA_STAGING GCP_DEPLOY_SA_PROD GCP_EVAL_SA_STAGING"
  "pulumi-state|Pulumi: state buckets and secrets keys|GCP_PROJECT_STAGING GCP_DEPLOY_SA_STAGING GCP_DEPLOY_SA_PROD"
  "reports-keys|Cloud KMS: the reports keys|GCP_PROJECT_STAGING GCP_BACKEND_SA_EU_STAGING GCP_BACKEND_SA_EU_PROD"
  "secrets|Secret Manager: each region's secrets|GCP_PROJECT_STAGING GCP_BACKEND_SA_EU_STAGING GCP_BACKEND_SA_EU_PROD"
  "vertex|Vertex AI and speech: live checks and staging's quota|GCP_PROJECT_STAGING DONE_GCP_APIS"
  "firebase|Firebase: Hosting and Test Lab|GCP_PROJECT_STAGING DONE_GCP_APIS"
  "domain|The domain, its hosts and the app's id|"
  "apple-team|Apple: your developer team|"
  "apple-app-id|Apple: the App ID|APP_BUNDLE_ID"
  "apple-services-id|Apple: the web Services ID|APP_BUNDLE_ID WEB_HOST_PROD WEB_HOST_STAGING"
  "apple-signin-key|Apple: the Sign in with Apple key|GCP_PROJECT_STAGING APP_BUNDLE_ID DONE_SECRETS"
  "app-store-connect|App Store Connect: the app record and TestFlight groups|APP_BUNDLE_ID"
  "google-branding|Google sign-in: branding and audience|DOMAIN WEB_HOST_PROD"
  "google-web-ios-clients|Google sign-in: the web and iOS client ids|APP_BUNDLE_ID APPLE_TEAM_ID WEB_HOST_PROD WEB_HOST_STAGING"
  "play-console|Google Play: the app and Play Integrity|ANDROID_PACKAGE"
  "play-testers|Google Play: the closed-testing Google Group|DONE_PLAY_CONSOLE"
  "play-submit-account|Google Play: the submit service account|DONE_PLAY_CONSOLE DONE_GCP_APIS"
  "eas-project|Expo: the EAS project|"
  "eas-android|Expo: the Android keystore and Play submit key|EXPO_OWNER EAS_PROJECT_ID APP_BUNDLE_ID PLAY_SUBMIT_SA"
  "eas-ios|Expo: the App Store Connect API key|EXPO_OWNER EAS_PROJECT_ID APP_BUNDLE_ID"
  "expo-token|Expo: CI's access token|EXPO_OWNER"
  "google-android-client|Google sign-in: the Android client id|ANDROID_PACKAGE ANDROID_UPLOAD_SHA1"
  "sentry-orgs|Sentry: the US and EU organizations|"
  "sentry-projects|Sentry: projects and DSNs|SENTRY_US_ORG SENTRY_EU_ORG"
  "email|Email: each region's provider|GCP_PROJECT_STAGING DOMAIN DONE_SECRETS"
  "play-signing|Google Play: the app-signing fingerprint|ANDROID_PACKAGE"
  "verify|Check and hand off|"
)
TOTAL_STAGES=${#STAGES[@]}   # 32

ROOT=$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel)
cd "$ROOT"
if [[ "$ENV_FILE" == .env ]]; then ENV_FILE=scripts/provisioned.env; fi

# Every gcloud call names its project. With no usable default, a call that
# forgets fails instead of landing in whichever project gcloud last used.
export CLOUDSDK_CORE_PROJECT=NO_DEFAULT_PROJECT

REPO=shrujancheruku/look-together
REPO_ID=1438296400   # GitHub's numeric ids, which a renamed or re-created repo can't take over
OWNER_ID=11743592
PROD=look-together
HOST_RE='^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$'
CLIENT_ID_RE='^[0-9]+-[a-z0-9]+\.apps\.googleusercontent\.com$'
SHA1_RE='^([0-9A-Fa-f]{2}:){19}[0-9A-Fa-f]{2}$'
DSN_RE='^https://[0-9a-f]+@[a-z0-9.-]+\.sentry\.io/[0-9]+$'
EMAIL_RE='^[^@ ]+@[^@ ]+\.[^@ ]+$'
STAGE_UNFINISHED=0
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

# ── Helpers ───────────────────────────────────────────────────────────────

ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# get KEY prints KEY's saved value, or nothing.
get() { _existing "$1" || true; }

# need KEY "Prompt" [DEFAULT] [REGEX] asks until the answer matches REGEX (any
# answer by default), then saves it. Enter takes DEFAULT on a first run.
need() {
  local key="$1" prompt="$2" def="${3:-}" re="${4:-.}"
  if [[ -n "$def" && -z "$(get "$key")" ]]; then prompt="$prompt [$def]"; fi
  while :; do
    ask "$key" "$prompt"
    if [[ -z "${!key}" ]]; then printf -v "$key" '%s' "$def"; fi
    if [[ "${!key}" =~ $re ]]; then break; fi
    warn "That doesn't look right. Try again."
  done
  write_env "$key" "${!key}"
}

upper() { printf '%s' "$1" | tr 'a-z-' 'A-Z_'; }
done_key() { printf 'DONE_%s' "$(upper "$1")"; }

# producer KEY names the stage that saves KEY.
producer() {
  case "$1" in
    DONE_*) printf '%s' "${1#DONE_}" | tr 'A-Z_' 'a-z-' ;;
    GCP_PROJECT_NUMBER_PROD) printf preflight ;;
    GCP_PROJECT_STAGING|GCP_PROJECT_NUMBER_STAGING) printf gcp-staging-project ;;
    GCP_*_SA_*) printf gcp-service-accounts ;;
    DOMAIN|WEB_HOST_*|APP_BUNDLE_ID|ANDROID_PACKAGE) printf domain ;;
    APPLE_TEAM_ID) printf apple-team ;;
    PLAY_SUBMIT_SA) printf play-submit-account ;;
    EXPO_OWNER|EAS_PROJECT_ID) printf eas-project ;;
    ANDROID_UPLOAD_SHA1) printf eas-android ;;
    SENTRY_*_ORG) printf sentry-orgs ;;
    *) printf 'an earlier stage' ;;
  esac
}

# project staging|prod is that environment's Google Cloud project.
project() { if [[ "$1" == prod ]]; then printf '%s' "$PROD"; else printf '%s' "$GCP_PROJECT_STAGING"; fi; }
# gcp_region eu|us is the Google Cloud region a region's backend runs in.
gcp_region() { if [[ "$1" == eu ]]; then printf europe-west1; else printf us-central1; fi; }

# founder is the Google account gcloud is signed in as: you.
founder() { gcloud auth list --filter=status:ACTIVE --format='value(account)' | head -n1; }
billing_account() { gcloud billing projects describe "$PROD" --format='value(billingAccountName)' | sed 's|^billingAccounts/||'; }

missing_tools() { local t; for t in "$@"; do command -v "$t" >/dev/null 2>&1 || printf ' %s' "$t"; done; }

# retry CMD... tries CMD a few times, 10 s apart: a new service account or
# binding takes a moment to reach every Google Cloud API.
retry() {
  local i
  for i in 1 2 3 4 5; do
    if "$@"; then return 0; fi
    note "Not there yet; trying again in 10 s."
    sleep 10
  done
  "$@"
}

service_account() {   # service_account PROJECT NAME "Display name"
  if ! gcloud iam service-accounts describe "$2@$1.iam.gserviceaccount.com" --project="$1" >/dev/null 2>&1; then
    gcloud iam service-accounts create "$2" --display-name="$3" --project="$1" --quiet
  fi
}

grant() {   # grant PROJECT MEMBER ROLE... adds project-level roles
  local p="$1" member="$2" role; shift 2
  for role in "$@"; do
    retry gcloud projects add-iam-policy-binding "$p" --member="$member" --role="$role" \
      --condition=None --format=none --quiet
  done
}

kms_key() {   # kms_key PROJECT GCP_REGION RING KEY makes the ring and symmetric key unless they exist
  if ! gcloud kms keyrings describe "$3" --location="$2" --project="$1" >/dev/null 2>&1; then
    gcloud kms keyrings create "$3" --location="$2" --project="$1" --quiet
  fi
  if ! gcloud kms keys describe "$4" --keyring="$3" --location="$2" --project="$1" >/dev/null 2>&1; then
    gcloud kms keys create "$4" --keyring="$3" --location="$2" --purpose=encryption --project="$1" --quiet
  fi
}

kms_grant() {   # kms_grant PROJECT GCP_REGION RING KEY MEMBER ROLE
  retry gcloud kms keys add-iam-policy-binding "$4" --keyring="$3" --location="$2" --project="$1" \
    --member="$5" --role="$6" --format=none --quiet
}

# secret PROJECT NAME GCP_REGION READER makes NAME, its data kept only in
# GCP_REGION, unless it exists, and lets READER read it.
secret() {
  local where
  if ! gcloud secrets describe "$2" --project="$1" >/dev/null 2>&1; then
    gcloud secrets create "$2" --replication-policy=user-managed --locations="$3" --project="$1" --quiet --format=none
  fi
  where=$(gcloud secrets describe "$2" --project="$1" --format='value(replication.userManaged.replicas[].location)')
  if [[ "$where" != "$3" ]]; then
    warn "$2 in $1 keeps its data in '${where:-every region}', not only $3. Delete it and re-run this stage."
  fi
  retry gcloud secrets add-iam-policy-binding "$2" --member="serviceAccount:$4" \
    --role=roles/secretmanager.secretAccessor --project="$1" --format=none --quiet
}

versions() {   # versions PROJECT SECRET counts its enabled versions
  gcloud secrets versions list "$2" --project="$1" --filter=state=ENABLED --format='value(name)' | grep -c . || true
}

# random_key prints 32 random bytes, base64url: straight into a pipe, never shown.
random_key() { openssl rand -base64 32 | tr '+/' '-_' | tr -d '=\n'; }

# api METHOD URL PROJECT [BODY] calls a Google API as you, with PROJECT paying
# the quota. Prints the HTTP status; the response is in $TMP/api.json.
api() {
  local args=(-sS -o "$TMP/api.json" -w '%{http_code}' -X "$1"
    -H "x-goog-user-project: $3" -H 'Content-Type: application/json')
  if [[ -n "${4:-}" ]]; then args+=(--data "$4"); fi
  curl "${args[@]}" -H @<(printf 'Authorization: Bearer %s\n' "$(gcloud auth print-access-token)") "$2" || true
}

# check STATUS LABEL reports one live call, with Google's message on a failure.
check() {
  local message
  if [[ "$1" == 200 ]]; then ok "$2"; return 0; fi
  message=$(jq -r '(if type == "array" then .[0] else . end) | .error.message // empty' "$TMP/api.json" 2>/dev/null || true)
  warn "$2: HTTP $1 ${message:0:200}"
  SKIPPED+=("$2 answered HTTP $1: fix it, then scripts/provision.sh vertex")
  return 1
}

enable_apis() {   # enable_apis PROJECT NAME... turns on NAME.googleapis.com, ten at a time
  local p="$1" batch=() name; shift
  for name in "$@"; do
    batch+=("$name.googleapis.com")
    if (( ${#batch[@]} == 10 )); then gcloud services enable "${batch[@]}" --project="$p" --quiet; batch=(); fi
  done
  if (( ${#batch[@]} )); then gcloud services enable "${batch[@]}" --project="$p" --quiet; fi
  ok "APIs on in $p"
}

budget() {   # budget PROJECT AMOUNT BILLING_ACCOUNT CURRENCY, unless one exists
  local name="$1 monthly" names
  names=$(gcloud billing budgets list --billing-account="$3" --billing-project="$PROD" --format='value(displayName)')
  if grep -qxF "$name" <<< "$names"; then
    ok "Budget \"$name\" exists; change its amount in the console if you need to."
    return 0
  fi
  gcloud billing budgets create --billing-account="$3" --billing-project="$PROD" --display-name="$name" \
    --budget-amount="$2$4" --filter-projects="projects/$1" --calendar-period=month \
    --threshold-rule=percent=0.5 --threshold-rule=percent=0.9 --threshold-rule=percent=1.0 --format=none --quiet
  ok "Budget \"$name\": $2 $4 a month"
}

wif_user() {   # wif_user PROJECT SERVICE_ACCOUNT PRINCIPAL_SET lets those GitHub tokens act as it
  retry gcloud iam service-accounts add-iam-policy-binding "$2" --member="$3" \
    --role=roles/iam.workloadIdentityUser --project="$1" --format=none --quiet
}

# kms_audit_logs PROJECT turns on Data Access audit logs for Cloud KMS alone. It
# writes only the policy's auditConfigs, so no role binding can be lost.
kms_audit_logs() {
  local status
  status=$(api POST "https://cloudresourcemanager.googleapis.com/v1/projects/$1:getIamPolicy" "$1" '{}')
  if [[ "$status" != 200 ]]; then warn "Couldn't read $1's IAM policy (HTTP $status)."; exit 1; fi
  jq '{policy: {etag: .etag, auditConfigs: (((.auditConfigs // []) | map(select(.service != "cloudkms.googleapis.com")))
        + [{service: "cloudkms.googleapis.com", auditLogConfigs: [{logType: "DATA_READ"}, {logType: "DATA_WRITE"}]}])},
      updateMask: "auditConfigs"}' "$TMP/api.json" > "$TMP/audit.json"
  status=$(api POST "https://cloudresourcemanager.googleapis.com/v1/projects/$1:setIamPolicy" "$1" "@$TMP/audit.json")
  if [[ "$status" != 200 ]]; then warn "Couldn't turn on KMS audit logs in $1 (HTTP $status)."; exit 1; fi
  ok "Cloud KMS Data Access audit logs on in $1"
}

firebase_on() {   # firebase_on PROJECT adds Firebase to it unless it's there
  local status op i
  status=$(api GET "https://firebase.googleapis.com/v1beta1/projects/$1" "$1")
  if [[ "$status" == 200 ]]; then ok "Firebase is on in $1"; return 0; fi
  status=$(api POST "https://firebase.googleapis.com/v1beta1/projects/$1:addFirebase" "$1" '{}')
  if [[ "$status" == 200 ]]; then
    op=$(jq -r .name "$TMP/api.json")
    for i in $(seq 1 24); do
      api GET "https://firebase.googleapis.com/v1beta1/$op" "$1" > /dev/null
      if [[ "$(jq -r '.done // false' "$TMP/api.json")" == true ]]; then
        if [[ -z "$(jq -r '.error.message // empty' "$TMP/api.json")" ]]; then ok "Firebase added to $1"; return 0; fi
        break
      fi
      sleep 5
    done
  fi
  warn "Couldn't add Firebase to $1 from here."
  open_url "https://console.firebase.google.com/"
  step "Create a project → Add Firebase to Google Cloud project → pick $1 → follow the steps."
  pause "Press Enter once Firebase is added to $1."
}

need_eas() {
  if command -v eas >/dev/null 2>&1; then return 0; fi
  if confirm "This stage needs the EAS CLI. Install it now (npm install --global eas-cli)?"; then
    npm install --global eas-cli
  else
    warn "Install it, then re-run this stage."
    exit 1
  fi
}

# eas_project_dir prints a scratch Expo project for eas credentials: the app
# isn't scaffolded yet, and EAS files credentials by project, bundle id and package.
eas_project_dir() {
  local dir="$TMP/eas"
  mkdir -p "$dir"
  jq -n --arg owner "$EXPO_OWNER" --arg id "$APP_BUNDLE_ID" --arg project "$EAS_PROJECT_ID" \
    '{expo: {name: "Look Together", slug: "look-together", owner: $owner,
      ios: {bundleIdentifier: $id}, android: {package: $id}, extra: {eas: {projectId: $project}}}}' > "$dir/app.json"
  printf '%s\n' '{"build": {"production": {}}, "submit": {"production": {}}}' > "$dir/eas.json"
  printf '%s\n' '{"name": "look-together", "private": true}' > "$dir/package.json"
  printf '%s' "$dir"
}

# ── Stages ────────────────────────────────────────────────────────────────

stage_preflight() {
  say "We'll set up everything the build needs (#194), one stage at a time."
  say "Values safe to publish go to $ENV_FILE, which you commit at the end."
  say "Secrets go only to Secret Manager, EAS or GitHub secrets, never to disk."
  printf '\n'
  local missing account number
  missing=$(missing_tools git gh gcloud curl jq openssl node npm dig)
  while [[ -n "$missing" ]]; do
    warn "Missing:$missing. On a Mac: brew install$missing (gcloud is brew install --cask google-cloud-sdk)."
    pause "Install them in another terminal, then press Enter to check again."
    missing=$(missing_tools git gh gcloud curl jq openssl node npm dig)
  done
  ok "Tools are installed."
  if ! command -v eas >/dev/null 2>&1; then
    if confirm "Install the EAS CLI for the Expo stages now (npm install --global eas-cli)?"; then
      npm install --global eas-cli
    else
      note "The Expo stages will offer again."
    fi
  fi

  if ! gh auth status >/dev/null 2>&1; then
    step "Signing you in to GitHub: gh sets CI's variables and secrets."
    gh auth login --hostname github.com --web
  fi
  if [[ "$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null)" != "$REPO" ]]; then
    warn "This checkout's GitHub remote isn't $REPO. Run the wizard from a clone of it."
    exit 1
  fi
  if [[ "$(gh api "repos/$REPO" --jq .permissions.admin 2>/dev/null)" != true ]]; then
    warn "gh is signed in as an account that can't administer $REPO. Sign in as its owner: gh auth login"
    exit 1
  fi
  ok "GitHub: signed in, and $REPO is yours."

  account=$(founder)
  while [[ -z "$account" ]] || ! confirm "Is $account the Google account that owns $PROD?"; do
    step "Signing you in to Google Cloud: choose the account that owns $PROD."
    gcloud auth login
    account=$(founder)
  done
  number=$(gcloud projects describe "$PROD" --format='value(projectNumber)')
  write_env GCP_PROJECT_PROD "$PROD"
  write_env GCP_PROJECT_NUMBER_PROD "$number"
  write_env GCP_REGION_EU "$(gcp_region eu)"
  write_env GCP_REGION_US "$(gcp_region us)"
  if [[ -z "$(billing_account)" ]]; then
    warn "$PROD has no billing account linked."
    open_url "https://console.cloud.google.com/billing/linkedaccount?project=$PROD"
    pause "Link one there, then press Enter."
  fi

  if gcloud auth application-default print-access-token >/dev/null 2>&1; then
    ok "Application Default Credentials are set up."
  elif confirm "Set up Application Default Credentials too? Pulumi and local live calls use them."; then
    gcloud auth application-default login --disable-quota-project
  else
    SKIPPED+=("Application Default Credentials: gcloud auth application-default login --disable-quota-project")
  fi
}

stage_gcp_staging_project() {
  local billing enabled number
  billing=$(billing_account)
  say "Staging gets its own project beside $PROD, on the same billing account ($billing)."
  need GCP_PROJECT_STAGING "Staging project id:" look-together-staging '^[a-z][a-z0-9-]{4,28}[a-z0-9]$'
  while ! gcloud projects describe "$GCP_PROJECT_STAGING" >/dev/null 2>&1; do
    if ! confirm "Create the project $GCP_PROJECT_STAGING and link it to billing account $billing?"; then
      STAGE_UNFINISHED=1
      SKIPPED+=("the staging project: scripts/provision.sh gcp-staging-project")
      return 0
    fi
    if gcloud projects create "$GCP_PROJECT_STAGING" --name="Look Together staging" --quiet; then break; fi
    warn "Couldn't create $GCP_PROJECT_STAGING. Project ids are global, so another account may hold it."
    need GCP_PROJECT_STAGING "Another staging project id:" "" '^[a-z][a-z0-9-]{4,28}[a-z0-9]$'
  done
  enabled=$(gcloud billing projects describe "$GCP_PROJECT_STAGING" --format='value(billingEnabled)')
  if [[ "$enabled" != True ]]; then
    if ! confirm "Link $GCP_PROJECT_STAGING to billing account $billing?"; then
      STAGE_UNFINISHED=1
      SKIPPED+=("billing for $GCP_PROJECT_STAGING: scripts/provision.sh gcp-staging-project")
      return 0
    fi
    gcloud billing projects link "$GCP_PROJECT_STAGING" --billing-account="$billing" --format=none --quiet
  fi
  ok "$GCP_PROJECT_STAGING exists, with billing."
  number=$(gcloud projects describe "$GCP_PROJECT_STAGING" --format='value(projectNumber)')
  write_env GCP_PROJECT_NUMBER_STAGING "$number"
}

stage_gcp_apis() {
  local apis=(aiplatform speech texttospeech run firestore secretmanager cloudkms iam iamcredentials sts
    artifactregistry compute logging monitoring storage cloudresourcemanager serviceusage firebase
    firebasehosting billingbudgets)
  say "We'll turn on the APIs the backend, CI and Pulumi use in both projects, plus Test Lab"
  say "and Google Play's in $PROD. It takes a minute or two."
  note "Pulumi doesn't turn APIs on: to add one, add it here and re-run this stage."
  enable_apis "$GCP_PROJECT_STAGING" "${apis[@]}"
  enable_apis "$PROD" "${apis[@]}" testing toolresults androidpublisher playintegrity
}

stage_gcp_budgets() {
  local billing currency
  billing=$(billing_account)
  currency=$(gcloud billing accounts describe "$billing" --format='value(currencyCode)')
  say "Each project gets a monthly budget that emails the billing account's admins at 50%, 90% and 100%."
  note "A budget only warns. Staging's hard stops are its spend ceiling and maxInstances 2."
  need BUDGET_STAGING "Staging's monthly budget, in $currency:" 25 '^[0-9]+$'
  need BUDGET_PROD "Production's monthly budget, in $currency:" 100 '^[0-9]+$'
  budget "$GCP_PROJECT_STAGING" "$BUDGET_STAGING" "$billing" "$currency"
  budget "$PROD" "$BUDGET_PROD" "$billing" "$currency"
}

stage_gcp_service_accounts() {
  local env p r sa deploy eval_sa
  say "Each project gets a runtime service account per region and one for CI's deploys;"
  say "staging gets one more for the live evaluation runs. CI gets no IAM or KMS admin"
  say "rights: this wizard sets those, so Pulumi never needs them."
  for env in staging prod; do
    p=$(project "$env")
    deploy="ci-deploy@$p.iam.gserviceaccount.com"
    for r in eu us; do
      sa="backend-$r@$p.iam.gserviceaccount.com"
      service_account "$p" "backend-$r" "Backend ($r)"
      grant "$p" "serviceAccount:$sa" roles/datastore.user roles/aiplatform.user roles/speech.client \
        roles/serviceusage.serviceUsageConsumer roles/logging.logWriter roles/monitoring.metricWriter
      write_env "GCP_BACKEND_SA_$(upper "$r")_$(upper "$env")" "$sa"
    done
    service_account "$p" ci-deploy "CI deploys"
    grant "$p" "serviceAccount:$deploy" roles/run.admin roles/artifactregistry.admin \
      roles/compute.loadBalancerAdmin roles/datastore.owner roles/logging.configWriter \
      roles/monitoring.editor roles/firebasehosting.admin roles/secretmanager.viewer \
      roles/serviceusage.serviceUsageConsumer
    for r in eu us; do
      retry gcloud iam service-accounts add-iam-policy-binding "backend-$r@$p.iam.gserviceaccount.com" \
        --member="serviceAccount:$deploy" --role=roles/iam.serviceAccountUser --project="$p" --format=none --quiet
    done
    write_env "GCP_DEPLOY_SA_$(upper "$env")" "$deploy"
  done
  eval_sa="ci-eval@$GCP_PROJECT_STAGING.iam.gserviceaccount.com"
  service_account "$GCP_PROJECT_STAGING" ci-eval "CI live evaluation"
  grant "$GCP_PROJECT_STAGING" "serviceAccount:$eval_sa" roles/aiplatform.user roles/serviceusage.serviceUsageConsumer
  write_env GCP_EVAL_SA_STAGING "$eval_sa"
}

stage_gcp_wif() {
  local mapping repo_only env p number condition pool verb key
  mapping="google.subject=assertion.sub,attribute.repository=assertion.repository"
  mapping+=",attribute.repository_id=assertion.repository_id,attribute.repository_owner_id=assertion.repository_owner_id"
  mapping+=",attribute.ref=assertion.ref"
  repo_only="assertion.repository_owner_id=='$OWNER_ID' && assertion.repository_id=='$REPO_ID'"
  say "GitHub Actions signs in to Google Cloud with its own short-lived token: no JSON keys."
  say "Only this repository's workflows qualify; in $PROD, only release tags (v…);"
  say "and staging deploys only from main."
  for env in staging prod; do
    p=$(project "$env")
    if [[ "$env" == prod ]]; then
      number=$GCP_PROJECT_NUMBER_PROD
      condition="$repo_only && assertion.ref.startsWith('refs/tags/v')"
    else
      number=$GCP_PROJECT_NUMBER_STAGING
      condition=$repo_only
    fi
    pool="projects/$number/locations/global/workloadIdentityPools/github"
    if ! gcloud iam workload-identity-pools describe github --location=global --project="$p" >/dev/null 2>&1; then
      gcloud iam workload-identity-pools create github --location=global --display-name="GitHub Actions" \
        --project="$p" --quiet
    fi
    if gcloud iam workload-identity-pools providers describe look-together --location=global \
        --workload-identity-pool=github --project="$p" >/dev/null 2>&1; then
      verb=update-oidc
    else
      verb=create-oidc
    fi
    gcloud iam workload-identity-pools providers "$verb" look-together --location=global \
      --workload-identity-pool=github --issuer-uri=https://token.actions.githubusercontent.com \
      --attribute-mapping="$mapping" --attribute-condition="$condition" --project="$p" --format=none --quiet
    if [[ "$env" == staging ]]; then
      wif_user "$p" "$GCP_DEPLOY_SA_STAGING" "principalSet://iam.googleapis.com/$pool/attribute.ref/refs/heads/main"
      wif_user "$p" "$GCP_EVAL_SA_STAGING" "principalSet://iam.googleapis.com/$pool/attribute.repository_id/$REPO_ID"
    else
      wif_user "$p" "$GCP_DEPLOY_SA_PROD" "principalSet://iam.googleapis.com/$pool/attribute.repository_id/$REPO_ID"
    fi
    write_env "GCP_WIF_PROVIDER_$(upper "$env")" "$pool/providers/look-together"
  done
  for key in GCP_PROJECT_STAGING GCP_PROJECT_PROD GCP_WIF_PROVIDER_STAGING GCP_WIF_PROVIDER_PROD \
      GCP_DEPLOY_SA_STAGING GCP_DEPLOY_SA_PROD GCP_EVAL_SA_STAGING; do
    set_var "$key" "$(get "$key")"
  done
  note "A new provider can take up to 5 minutes before GitHub's tokens work."
  note "Fork pull requests get no token, and no workflow should use pull_request_target."
}

stage_pulumi_state() {
  local env p key deploy me bucket
  say "Each project keeps its Pulumi state in its own bucket, in europe-west1, with the"
  say "secrets in that state encrypted by the 'state' key in a 'pulumi' key ring."
  warn "Google Cloud never deletes a key ring or a key: only their versions can be destroyed."
  if ! confirm "Make the buckets and keys in $GCP_PROJECT_STAGING and $PROD?"; then
    STAGE_UNFINISHED=1
    SKIPPED+=("Pulumi's state buckets and keys: scripts/provision.sh pulumi-state")
    return 0
  fi
  me=$(founder)
  for env in staging prod; do
    p=$(project "$env")
    key="PULUMI_BACKEND_URL_$(upper "$env")"
    deploy="ci-deploy@$p.iam.gserviceaccount.com"
    bucket=$(get "$key")
    bucket=${bucket:-gs://$p-pulumi-state}
    while ! gcloud storage buckets describe "$bucket" --project="$p" >/dev/null 2>&1; do
      if gcloud storage buckets create "$bucket" --location=europe-west1 --uniform-bucket-level-access \
          --public-access-prevention --project="$p" --quiet; then
        break
      fi
      warn "Couldn't create $bucket. Bucket names are global, so another account may hold it."
      need "$key" "Another bucket for $env's state (gs://…):" "" '^gs://[a-z0-9][a-z0-9._-]{1,61}[a-z0-9]$'
      bucket=$(get "$key")
    done
    gcloud storage buckets update "$bucket" --versioning --project="$p" --format=none --quiet
    retry gcloud storage buckets add-iam-policy-binding "$bucket" --member="serviceAccount:$deploy" \
      --role=roles/storage.objectAdmin --project="$p" --format=none --quiet
    write_env "$key" "$bucket"
    kms_key "$p" europe-west1 pulumi state
    kms_grant "$p" europe-west1 pulumi state "serviceAccount:$deploy" roles/cloudkms.cryptoKeyEncrypterDecrypter
    kms_grant "$p" europe-west1 pulumi state "user:$me" roles/cloudkms.cryptoKeyEncrypterDecrypter
    write_env "PULUMI_SECRETS_PROVIDER_$(upper "$env")" \
      "gcpkms://projects/$p/locations/europe-west1/keyRings/pulumi/cryptoKeys/state"
    set_var "$key" "$(get "$key")"
    set_var "PULUMI_SECRETS_PROVIDER_$(upper "$env")" "$(get "PULUMI_SECRETS_PROVIDER_$(upper "$env")")"
  done
}

stage_reports_keys() {
  local env p r where me
  say "Each region's Reports are encrypted with that region's 'reports' key: its backend can"
  say "only encrypt, and only you can decrypt. Cloud KMS logs every use of those keys."
  warn "Google Cloud never deletes a key ring or a key."
  if ! confirm "Make the 'reports' keys in both regions of $GCP_PROJECT_STAGING and $PROD?"; then
    STAGE_UNFINISHED=1
    SKIPPED+=("the reports keys: scripts/provision.sh reports-keys")
    return 0
  fi
  me=$(founder)
  for env in staging prod; do
    p=$(project "$env")
    for r in eu us; do
      where=$(gcp_region "$r")
      kms_key "$p" "$where" look-together reports
      kms_grant "$p" "$where" look-together reports "serviceAccount:backend-$r@$p.iam.gserviceaccount.com" \
        roles/cloudkms.cryptoKeyEncrypter
      kms_grant "$p" "$where" look-together reports "user:$me" roles/cloudkms.cryptoKeyDecrypter
      write_env "REPORTS_KEY_$(upper "$r")_$(upper "$env")" \
        "projects/$p/locations/$where/keyRings/look-together/cryptoKeys/reports"
    done
    kms_audit_logs "$p"
  done
}

stage_secrets() {
  local env p r where reader
  say "Each region's secrets, in both projects:"
  step "session-signing-key-<region>: two random versions, so the backend has a current and a previous key from the start"
  step "ip-hash-salt-<region>: one random version, never rotated, since rotating it resets every meter"
  step "apple-signin-key-<region>: filled from Apple's .p8 in the apple-signin-key stage"
  step "email-api-key-<region>: filled once #103 picks the email provider"
  note "Cloud Run can't mount regional secrets, so each is a global secret whose data is kept"
  note "only in its region's Google Cloud region. Values are made in memory and never shown."
  for env in staging prod; do
    p=$(project "$env")
    for r in eu us; do
      where=$(gcp_region "$r")
      reader="backend-$r@$p.iam.gserviceaccount.com"
      secret "$p" "session-signing-key-$r" "$where" "$reader"
      while (( $(versions "$p" "session-signing-key-$r") < 2 )); do
        random_key | gcloud secrets versions add "session-signing-key-$r" --data-file=- --project="$p" --format=none --quiet
      done
      secret "$p" "ip-hash-salt-$r" "$where" "$reader"
      if (( $(versions "$p" "ip-hash-salt-$r") == 0 )); then
        random_key | gcloud secrets versions add "ip-hash-salt-$r" --data-file=- --project="$p" --format=none --quiet
      fi
      secret "$p" "apple-signin-key-$r" "$where" "$reader"
      secret "$p" "email-api-key-$r" "$where" "$reader"
      ok "$p · $r: secrets ready in $where"
    done
  done
}

stage_vertex() {
  local env p r status failed=0
  say "One tiny Gemini 3.8 Flash call, and a list of speech recognizers and voices, in each"
  say "region of both projects, through the EU and US endpoints the backend uses."
  for env in staging prod; do
    p=$(project "$env")
    for r in eu us; do
      status=$(api POST "https://aiplatform.$r.rep.googleapis.com/v1/projects/$p/locations/$r/publishers/google/models/gemini-3.8-flash:generateContent" \
        "$p" '{"contents": [{"role": "user", "parts": [{"text": "Reply with OK."}]}]}')
      check "$status" "Gemini 3.8 Flash · $p · $r" || failed=1
      status=$(api GET "https://$r-speech.googleapis.com/v2/projects/$p/locations/$r/recognizers" "$p")
      check "$status" "Speech-to-Text · $p · $r" || failed=1
      status=$(api GET "https://$r-texttospeech.googleapis.com/v1/voices?languageCode=en-GB" "$p")
      check "$status" "Text-to-Speech · $p · $r" || failed=1
    done
  done
  printf '\n'
  say "Now staging's quota. Gemini throughput comes from the account's Vertex AI usage tier,"
  say "so there may be no per-project quota to lower. Staging is then held by its budget, its"
  say "spend ceiling and maxInstances 2."
  open_url "https://console.cloud.google.com/iam-admin/quotas?project=$GCP_PROJECT_STAGING"
  step "Filter for Vertex AI API and search for gemini-3.8-flash."
  step "If a per-minute quota for it is listed, lower it for staging from that row's edit control."
  need STAGING_VERTEX_QUOTA "The value you set (per minute), or none if there's no quota to lower:" "" '^(none|[0-9]+)$'
  if (( failed )); then STAGE_UNFINISHED=1; fi
}

stage_firebase() {
  say "Firebase Hosting serves the web app, one site per project, and Test Lab runs the"
  say "Android device tests in $PROD."
  firebase_on "$GCP_PROJECT_STAGING"
  firebase_on "$PROD"
  if gcloud firebase test android models list --project="$PROD" --format='value(id)' >/dev/null 2>&1; then
    ok "Test Lab answers in $PROD"
  else
    warn "Test Lab didn't answer in $PROD."
    open_url "https://console.firebase.google.com/project/$PROD/testlab"
    pause "Open Test Lab there once so it finishes setting up, then press Enter."
  fi
  note "gcloud firebase test is deprecated and stops on 30 Sep 2027; gcloud beta device-run replaces it."
}

stage_domain() {
  local suggested
  say "Look Together needs one domain: the API and web hosts hang off it. DNS records come later, with #163."
  if ! confirm "Is the domain registered? (If not, register it at a registrar of your choice first.)"; then
    STAGE_UNFINISHED=1
    SKIPPED+=("the domain, its hosts and the app's id: scripts/provision.sh domain (the Apple, Google and Play stages wait for it)")
    return 0
  fi
  need DOMAIN "The domain:" "" "$HOST_RE"
  if [[ -z "$(dig +short NS "$DOMAIN" 2>/dev/null || true)" ]]; then
    warn "$DOMAIN has no nameservers yet. Check the registration."
  fi
  write_env API_HOST_EU_PROD "eu.api.$DOMAIN"
  write_env API_HOST_US_PROD "us.api.$DOMAIN"
  write_env API_HOST_EU_STAGING "eu.api.staging.$DOMAIN"
  write_env API_HOST_US_STAGING "us.api.staging.$DOMAIN"
  need WEB_HOST_PROD "Production web host:" "$DOMAIN" "$HOST_RE"
  need WEB_HOST_STAGING "Staging web host:" "staging.$DOMAIN" "$HOST_RE"
  printf '\n'
  say "One id names the app in both stores: the iOS bundle id and the Android package."
  warn "It can't change once the App Store Connect record and the Play app exist."
  suggested=$(printf '%s' "$DOMAIN" | tr -d '-' | awk -F. '{ for (i = NF; i > 1; i--) printf "%s.", $i; print $1 }')
  need APP_BUNDLE_ID "The app's id (lowercase letters and digits, dot-separated):" "$suggested" \
    '^[a-z][a-z0-9]*(\.[a-z][a-z0-9]*)+$'
  write_env ANDROID_PACKAGE "$APP_BUNDLE_ID"
}

stage_apple_team() {
  say "Sign in with Apple, App Attest and the App Store need a paid Apple Developer Program membership."
  open_url "https://developer.apple.com/account"
  step "Sign in. If you haven't joined the program, enrol from that page first; Apple can take a day or two."
  step "Under Membership details, copy the Team ID."
  need APPLE_TEAM_ID "Team ID (10 characters):" "" '^[A-Z0-9]{10}$'
}

stage_apple_app_id() {
  say "The App ID is the iOS app's identity, $APP_BUNDLE_ID, with Sign in with Apple and App Attest on."
  open_url "https://developer.apple.com/account/resources/identifiers/list"
  step "Click + → App IDs → Continue → App → Continue."
  step "Description: Look Together. Bundle ID: Explicit, $APP_BUNDLE_ID."
  step "Under Capabilities, tick Sign in with Apple (leave it as a primary App ID) and App Attest."
  step "Continue → Register."
  note "If App Attest isn't listed, EAS turns it on from the app's entitlements on the first build."
  pause "Press Enter once the App ID is registered."
}

stage_apple_services_id() {
  local prod_url="https://$WEB_HOST_PROD/auth/apple/callback" staging_url="https://$WEB_HOST_STAGING/auth/apple/callback"
  say "The web app signs in with Apple through a Services ID, which names its domains and return URLs."
  need APPLE_SERVICES_ID "Services ID:" "$APP_BUNDLE_ID.web" '^[a-z0-9]+(\.[a-z0-9-]+)+$'
  open_url "https://developer.apple.com/account/resources/identifiers/list"
  step "Click + → Services IDs → Continue. Description: Look Together web. Identifier: $APPLE_SERVICES_ID."
  step "Continue → Register. Then click $APPLE_SERVICES_ID in the list and tick Sign in with Apple → Configure."
  step "Primary App ID: $APP_BUNDLE_ID. Domains and Subdomains: $WEB_HOST_PROD, $WEB_HOST_STAGING"
  step "Return URLs: $prod_url, $staging_url"
  step "Next → Done → Continue → Save."
  note "#101's web sign-in uses this return path. You can add URLs later on the same screen."
  pause "Press Enter once it's saved."
  write_env APPLE_RETURN_URLS "$prod_url $staging_url"
}

stage_apple_signin_key() {
  local p8 env p r name P8_PATH=""
  say "The backend proves who it is to Apple with a private key from your developer account."
  say "We put it in each region's apple-signin-key secret, in both projects, and nowhere else."
  open_url "https://developer.apple.com/account/resources/authkeys/list"
  step "Click + . Key Name: Look Together sign-in. Tick Sign in with Apple → Configure."
  step "Primary App ID: $APP_BUNDLE_ID → Save → Continue → Register → Download."
  warn "Apple lets you download the key only once. Keep a copy in your password manager."
  need APPLE_SIGNIN_KEY_ID "Its Key ID (10 characters):" "" '^[A-Z0-9]{10}$'
  p8="$HOME/Downloads/AuthKey_$APPLE_SIGNIN_KEY_ID.p8"
  while [[ ! -f "$p8" ]] || ! grep -q 'BEGIN PRIVATE KEY' "$p8"; do
    ask P8_PATH "Path to the downloaded AuthKey_$APPLE_SIGNIN_KEY_ID.p8:"
    p8="${P8_PATH/#\~/$HOME}"
  done
  for env in staging prod; do
    p=$(project "$env")
    for r in eu us; do
      name="apple-signin-key-$r"
      if (( $(versions "$p" "$name") > 0 )) && ! confirm "$name in $p already holds a key. Replace it with this one?"; then
        continue
      fi
      gcloud secrets versions add "$name" --data-file="$p8" --project="$p" --format=none --quiet
      ok "$name in $p"
    done
  done
  if confirm "Saved in your password manager? Delete $p8 from this Mac now?"; then rm -f "$p8"; fi
}

stage_app_store_connect() {
  say "The App Store Connect record holds TestFlight and the App Store listing."
  open_url "https://appstoreconnect.apple.com/apps"
  step "Click + → New App. Platforms: iOS. Name: Look Together (if it's taken in the store, pick a variant)."
  step "Primary Language: yours. Bundle ID: $APP_BUNDLE_ID. SKU: look-together. User Access: Full Access → Create."
  step "Open App Information and copy the Apple ID (a number) under General Information."
  need ASC_APP_ID "Apple ID:" "" '^[0-9]+$'
  printf '\n'
  say "TestFlight needs an internal group before an external one."
  step "TestFlight tab → + beside Internal Testing → name it Team, add yourself → Create."
  step "Then + beside External Testing → name the group → Create."
  note "External testers see a build only after Beta App Review, which the first preview build (#164) goes through."
  need TESTFLIGHT_GROUP "The external group's name:" Testers
}

stage_google_branding() {
  say "Google's sign-in screen shows the app's name and domain from the Google Auth Platform in $PROD."
  open_url "https://console.developers.google.com/auth/branding?project=$PROD"
  step "If it asks you to get started: App name Look Together, your support email → Next;"
  step "Audience: External → Next; your contact email → Next; agree → Create."
  step "Under Authorized domains, add $DOMAIN → Save. Add the home page and privacy policy links once they exist."
  pause "Press Enter once branding is saved."
  open_url "https://console.developers.google.com/auth/audience?project=$PROD"
  step "Check it's External. Leave the publishing status on Testing until the privacy policy is live."
  step "While it's in Testing, add the Google accounts that will try sign-in as test users."
  pause "Press Enter when done."
}

stage_google_web_ios_clients() {
