  need GOOGLE_WEB_CLIENT_ID "Web client ID:" "" "$CLIENT_ID_RE"
  printf '\n'
  step "CREATE CLIENT again → Application type: iOS. Name: Look Together iOS."
  step "Bundle ID: $APP_BUNDLE_ID. App Store ID: ${asc:-leave it empty}. Team ID: $APPLE_TEAM_ID → Create."
  need GOOGLE_IOS_CLIENT_ID "iOS client ID:" "" "$CLIENT_ID_RE"
