stage_play_console() {
  say "Google Play needs the app created before anything can be uploaded to it."
  open_url "https://play.google.com/console"
  step "Sign in with your Play developer account (registering costs a one-time fee)."
  step "Create app → App name: Look Together. Default language: yours. App. Free."
  step "Tick the declarations → Create app."
  note "Its package, $ANDROID_PACKAGE, is fixed by the first upload, which EAS Submit makes."
  printf '\n'
  say "Then link Play Integrity to $PROD, so the backend can check requests come from the real app."
  step "In the app: Protected with Play → Play Integrity API → Get started (or its settings)."
  step "Link a Cloud project → $PROD → Link."
