stage_play_submit_account() {
  local sa="play-submit@$PROD.iam.gserviceaccount.com"
  say "EAS Submit uploads builds to Play as a service account in $PROD with no Google Cloud roles."
  say "Its only rights are the Play Console permissions you give it here."
  service_account "$PROD" play-submit "EAS Submit to Google Play"
  write_env PLAY_SUBMIT_SA "$sa"
  open_url "https://play.google.com/console"
  step "Users and permissions → Invite new users → Email address: $sa"
