stage_eas_project() {
  local me
  need_eas
  if ! eas whoami >/dev/null 2>&1; then
    step "Signing you in to Expo."
    eas login
  fi
  me=$(eas whoami 2>/dev/null | head -n1 || true)
  say "EAS builds, signs and submits the app. Its project is look-together."
  need EXPO_OWNER "Expo account or organization that owns it:" "$me" '^[A-Za-z0-9_-]+$'
  open_url "https://expo.dev/accounts/$EXPO_OWNER/projects"
  step "Create a project (or open look-together if it's there). Display name: Look Together. Slug: look-together."
  step "Copy its ID from the project's page."
  need EAS_PROJECT_ID "Project ID:" "" '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
}

stage_eas_android() {
  local dir key="$TMP/play-submit.json" existing
  need_eas
  dir=$(eas_project_dir)
  say "EAS makes and keeps the Android upload keystore, and submits to Play with a play-submit key."
  existing=$(gcloud iam service-accounts keys list --iam-account="$PLAY_SUBMIT_SA" --managed-by=user \
    --project="$PROD" --format='value(name)')
  if [[ -z "$existing" ]] || confirm "play-submit already has a key. Make a new one for EAS anyway?"; then
    gcloud iam service-accounts keys create "$key" --iam-account="$PLAY_SUBMIT_SA" --project="$PROD" --quiet
    note "The key file lives in a private temp folder until EAS has it, then it's deleted."
  fi
  step "In the menu below: production (if asked) → Keystore: Manage everything needed to build your project"
  step "→ Set up a new keystore → let EAS generate it. Note the SHA1 fingerprint it shows."
  if [[ -f "$key" ]]; then
    step "Back at the menu: Google Service Account → Manage your Google Service Account Key for Play Store"
    step "Submissions → Set up a Google Service Account Key… → Upload a new service account key → $key"
  fi
  step "Then Go back → Exit."
  pause "Press Enter to start eas credentials."
  if ! (cd "$dir" && eas credentials -p android); then
    warn "eas credentials stopped early. The project's Credentials page does the same:"
    open_url "https://expo.dev/accounts/$EXPO_OWNER/projects/look-together/credentials"
    pause "Press Enter once the keystore and the service account key are set there."
  fi
  rm -f "$key"
  if ! confirm "Does EAS hold the upload keystore now, with its SHA1 fingerprint showing?"; then
    STAGE_UNFINISHED=1
    SKIPPED+=("the Android upload keystore: the first eas build offers to make one; then scripts/provision.sh eas-android")
    return 0
  fi
  note "Lost the fingerprint? eas credentials -p android shows it again, as does the Credentials page."
  need ANDROID_UPLOAD_SHA1 "Keystore SHA1 fingerprint (AA:BB:…):" "" "$SHA1_RE"
  write_env ANDROID_UPLOAD_SHA1 "$(printf '%s' "$ANDROID_UPLOAD_SHA1" | tr 'a-f' 'A-F')"
}

stage_eas_ios() {
  local dir
  need_eas
  dir=$(eas_project_dir)
  say "EAS Submit uploads to App Store Connect with an API key, which EAS makes for you."
  step "In the menu below: production (if asked) → sign in with your Apple ID when it asks."
  step "App Store Connect: Manage your API Key → Set up your project to use an API Key for EAS Submit"
  step "→ Generate a new App Store Connect API Key. Then Go back → Exit."
  note "EAS makes the distribution certificate and provisioning profile on the first build."
  pause "Press Enter to start eas credentials."
  if ! (cd "$dir" && eas credentials -p ios); then
    warn "eas credentials stopped early. Make the key by hand instead:"
    open_url "https://appstoreconnect.apple.com/access/integrations/api"
    step "Team Keys → Generate API Key, Admin access → download it (only once); note its Key ID and the Issuer ID."
    open_url "https://expo.dev/accounts/$EXPO_OWNER/projects/look-together/credentials"
    step "Upload it there as the iOS app's App Store Connect API key, then delete the download."
    pause "Press Enter once EAS has the key."
  fi
}

stage_expo_token() {
  local EXPO_TOKEN="" names
  say "The release workflow builds and submits through EAS, so CI needs an Expo access token."
  open_url "https://expo.dev/settings/access-tokens"
  step "Create token → name it look-together GitHub Actions; if offered, limit it to $EXPO_OWNER → Create."
  step "Copy it: it's shown once."
  while [[ -z "$EXPO_TOKEN" ]]; do ask_secret EXPO_TOKEN "Paste the token (hidden):"; done
  set_secret EXPO_TOKEN "$EXPO_TOKEN"
  names=$(gh secret list --json name --jq '.[].name' 2>/dev/null || true)
  if ! grep -qx EXPO_TOKEN <<< "$names"; then STAGE_UNFINISHED=1; fi
}

stage_google_android_client() {
  say "Android's Google sign-in checks the app's package and signing fingerprint: one client per fingerprint."
  open_url "https://console.developers.google.com/auth/clients?project=$PROD"
  step "CREATE CLIENT → Application type: Android. Name: Look Together Android (upload key)."
  step "Package name: $ANDROID_PACKAGE. SHA-1 certificate fingerprint: $ANDROID_UPLOAD_SHA1 → Create."
  need GOOGLE_ANDROID_CLIENT_ID_UPLOAD "Android client ID:" "" "$CLIENT_ID_RE"
  note "Builds from Play carry Play's own signature; the play-signing stage adds its client after the first upload."
