stage_sentry_orgs() {
  local region where slug
  say "Errors stay in their region: one Sentry organization in the US and one in the EU, each on"
  say "the free Developer plan. An organization's data storage location is fixed when it's made."
  for region in US EU; do
    if [[ "$region" == US ]]; then where="United States"; else where="European Union"; fi
    printf '\n'
    open_url "https://sentry.io/organizations/new/"
    step "Organization name: Look Together $region. Data Storage Location: $where → Create."
    note "If it starts on a trial, it drops to the Developer plan when the trial ends."
    need "SENTRY_${region}_ORG" "The $region organization's slug (from its URL):" "" '^[a-z0-9][a-z0-9-]*$'
    slug=$(get "SENTRY_${region}_ORG")
    open_url "https://sentry.io/settings/$slug/security-and-privacy/"
    step "Turn on Prevent Storing of IP Addresses, Data Scrubber, Use Default Scrubbers and Enhanced Privacy."
    step "Advanced Data Scrubbing → Add Rule: Method Remove, Data Type Anything, Source \$user.geo.** → Save."
    note "Not storing IPs doesn't stop Sentry working out a location from them; that rule drops it."
    pause "Press Enter once both are saved."
  done
}

stage_sentry_projects() {
  local region slug
  say "Each organization gets two projects, app and backend. DSNs are public: builds bundle them."
  for region in US EU; do
    slug=$(get "SENTRY_${region}_ORG")
    printf '\n'
    open_url "https://sentry.io/organizations/$slug/projects/new/"
    step "Platform: React Native. Project name: app → Create Project. Copy the DSN it shows."
    need "SENTRY_${region}_DSN_APP" "$region app DSN:" "" "$DSN_RE"
    open_url "https://sentry.io/organizations/$slug/projects/new/"
    step "Platform: Node.js. Project name: backend → Create Project. Copy the DSN."
    need "SENTRY_${region}_DSN_BACKEND" "$region backend DSN:" "" "$DSN_RE"
  done
  note "Lost a DSN? Settings → Projects → the project → Client Keys (DSN)."
}

stage_email() {
  local r env p EMAIL_KEY=""
  say "Each region sends its sign-in codes by email through a provider in that region, which #103 picks."
  if ! confirm "Has #103 picked the email provider for each region?"; then
    note "Nothing to set up yet: the email-api-key secrets wait, empty."
    STAGE_UNFINISHED=1
    SKIPPED+=("email providers, domain verification and API keys: once #103 decides, scripts/provision.sh email")
    return 0
  fi
  for r in eu us; do
    printf '\n'
    need "EMAIL_PROVIDER_$(upper "$r")" "The $(upper "$r") provider's name:"
    step "Sign up with it, keeping data in the $(upper "$r"). Verify the sending domain #103 names (under $DOMAIN):"
    step "add the SPF and DKIM records it gives you at your DNS host."
    step "Make one API key per environment that can only send email."
    for env in staging prod; do
      p=$(project "$env")
      EMAIL_KEY=""
      while [[ -z "$EMAIL_KEY" ]]; do ask_secret EMAIL_KEY "Paste the $(upper "$r") key for $env (hidden):"; done
      printf '%s' "$EMAIL_KEY" | gcloud secrets versions add "email-api-key-$r" --data-file=- --project="$p" --format=none --quiet
      ok "email-api-key-$r in $p"
    done
  done
  printf '\n'
  say "Apple's private relay forwards email only from domains you register with Apple."
  open_url "https://developer.apple.com/account/resources/services/list"
  step "Sign in with Apple for Email Communication → Configure → + beside Email Sources → the sending domain → Register."
  note "Apple checks the domain's SPF record; DKIM is recommended."
  pause "Press Enter once it's registered."
}

stage_play_signing() {
  say "Play re-signs builds with its app-signing key, so Google sign-in needs that fingerprint too."
  if ! confirm "Has EAS Submit uploaded a build to Play yet?"; then
    note "Come back after the first upload (#164)."
    STAGE_UNFINISHED=1
    SKIPPED+=("Play's app-signing fingerprint and its Android client: after the first upload, scripts/provision.sh play-signing")
    return 0
  fi
  open_url "https://play.google.com/console"
  step "In the app: Protected with Play → Manage Play app signing."
  step "Copy the SHA-1 under App signing key certificate."
  need PLAY_APP_SIGNING_SHA1 "App signing SHA-1:" "" "$SHA1_RE"
  write_env PLAY_APP_SIGNING_SHA1 "$(printf '%s' "$PLAY_APP_SIGNING_SHA1" | tr 'a-f' 'A-F')"
  open_url "https://console.developers.google.com/auth/clients?project=$PROD"
  step "CREATE CLIENT → Application type: Android. Name: Look Together Android (Play signing)."
  step "Package name: $ANDROID_PACKAGE. SHA-1 certificate fingerprint: $PLAY_APP_SIGNING_SHA1 → Create."
  need GOOGLE_ANDROID_CLIENT_ID_PLAY "Android client ID:" "" "$CLIENT_ID_RE"
  note "If that page lists another certificate you ship with, add a client for it the same way."
}

stage_verify() {
  local key i id title missing="" unfinished="" vars names branch=chore/provisioned-values
  local expected="GCP_PROJECT_PROD GCP_PROJECT_NUMBER_PROD GCP_PROJECT_STAGING GCP_PROJECT_NUMBER_STAGING
    GCP_BACKEND_SA_EU_STAGING GCP_BACKEND_SA_US_STAGING GCP_BACKEND_SA_EU_PROD GCP_BACKEND_SA_US_PROD
    GCP_DEPLOY_SA_STAGING GCP_DEPLOY_SA_PROD GCP_EVAL_SA_STAGING GCP_WIF_PROVIDER_STAGING GCP_WIF_PROVIDER_PROD
    PULUMI_BACKEND_URL_STAGING PULUMI_BACKEND_URL_PROD PULUMI_SECRETS_PROVIDER_STAGING PULUMI_SECRETS_PROVIDER_PROD
    REPORTS_KEY_EU_STAGING REPORTS_KEY_US_STAGING REPORTS_KEY_EU_PROD REPORTS_KEY_US_PROD STAGING_VERTEX_QUOTA
    DOMAIN API_HOST_EU_PROD API_HOST_US_PROD API_HOST_EU_STAGING API_HOST_US_STAGING WEB_HOST_PROD WEB_HOST_STAGING
    APP_BUNDLE_ID ANDROID_PACKAGE APPLE_TEAM_ID APPLE_SERVICES_ID APPLE_RETURN_URLS APPLE_SIGNIN_KEY_ID
    ASC_APP_ID TESTFLIGHT_GROUP GOOGLE_WEB_CLIENT_ID GOOGLE_IOS_CLIENT_ID GOOGLE_IOS_URL_SCHEME
    GOOGLE_ANDROID_CLIENT_ID_UPLOAD ANDROID_UPLOAD_SHA1 PLAY_TESTERS_GROUP PLAY_SUBMIT_SA EXPO_OWNER EAS_PROJECT_ID
    SENTRY_US_ORG SENTRY_EU_ORG SENTRY_US_DSN_APP SENTRY_US_DSN_BACKEND SENTRY_EU_DSN_APP SENTRY_EU_DSN_BACKEND"
  local ci_vars="GCP_PROJECT_STAGING GCP_PROJECT_PROD GCP_WIF_PROVIDER_STAGING GCP_WIF_PROVIDER_PROD
    GCP_DEPLOY_SA_STAGING GCP_DEPLOY_SA_PROD GCP_EVAL_SA_STAGING PULUMI_BACKEND_URL_STAGING PULUMI_BACKEND_URL_PROD
    PULUMI_SECRETS_PROVIDER_STAGING PULUMI_SECRETS_PROVIDER_PROD"
  for key in $expected; do
    if [[ -z "$(get "$key")" ]]; then missing="$missing $key"; fi
  done
  for i in "${!STAGES[@]}"; do
    IFS='|' read -r id title _ <<< "${STAGES[$i]}"
    if [[ "$id" != verify && "$(get "$(done_key "$id")")" != yes ]]; then unfinished="$unfinished $id"; fi
  done
  if [[ -n "$unfinished" ]]; then warn "Stages not done yet:$unfinished"; else ok "Every stage is done."; fi
  if [[ -n "$missing" ]]; then warn "Values not saved yet:$missing"; else ok "Every value is saved in $ENV_FILE."; fi

  vars=$(gh variable list --json name --jq '.[].name' 2>/dev/null || true)
  missing=""
  for key in $ci_vars; do
    if ! grep -qx "$key" <<< "$vars"; then missing="$missing $key"; fi
  done
  if [[ -n "$missing" ]]; then warn "GitHub variables not set yet:$missing"; else ok "CI's GitHub variables are set."; fi
  names=$(gh secret list --json name --jq '.[].name' 2>/dev/null || true)
  if grep -qx EXPO_TOKEN <<< "$names"; then ok "GitHub secret EXPO_TOKEN is set."; else warn "GitHub secret EXPO_TOKEN isn't set yet."; fi

  if grep -Eq 'PRIVATE KEY|private_key|ghp_|github_pat_|AIza' "$ENV_FILE"; then
    warn "$ENV_FILE holds something that looks secret. Remove it before committing."
    exit 1
  fi
  ok "Nothing in $ENV_FILE looks secret."

  printf '\n'
  say "Tick off what's done on #194."
  open_url "https://github.com/$REPO/issues/194"
  if [[ -n "$(git status --porcelain -- "$ENV_FILE" 2>/dev/null)" ]] \
      && confirm "Commit $ENV_FILE on $branch and open a pull request?"; then
    if git show-ref --verify --quiet "refs/heads/$branch"; then git switch "$branch"; else git switch -c "$branch"; fi
    git add -- "$ENV_FILE"
    git commit -m "chore: record the provisioned values (#194)" -- "$ENV_FILE"
    git push -u origin "$branch"
    gh pr create --title "chore: record the provisioned values" \
      --body "The public values scripts/provision.sh saved for #194. Secrets live in Secret Manager, EAS and GitHub secrets, not here."
    note "You're on $branch now: git switch main to go back."
  fi
}

# ── Running ───────────────────────────────────────────────────────────────

# run_stage N [skip] runs the Nth stage (from 0) after loading the values it
# reads. If one isn't saved yet, it stops, or with skip moves on.
run_stage() {
  local id title needs key value missing=""
  IFS='|' read -r id title needs <<< "${STAGES[$1]}"
  for key in $needs; do
    value=$(get "$key")
    if [[ -z "$value" ]]; then missing="$missing $key"; else printf -v "$key" '%s' "$value"; fi
  done
  _STAGE_INDEX=$1
  if [[ -n "$missing" ]]; then
    for key in $missing; do
      warn "Stage $(($1 + 1))/$TOTAL_STAGES · $title waits for $key: run scripts/provision.sh $(producer "$key")"
    done
    if [[ "${2:-}" != skip ]]; then exit 1; fi
    SKIPPED+=("$title: waits for$missing, then scripts/provision.sh $id")
    return 0
  fi
  stage "$title"
  STAGE_UNFINISHED=0
  "stage_${id//-/_}"
  if (( STAGE_UNFINISHED )) || [[ "$id" == verify ]]; then return 0; fi
  write_env "$(done_key "$id")" yes
}

stage_number() {   # stage_number ID prints its index, or fails
  local i
  for i in "${!STAGES[@]}"; do
    if [[ "${STAGES[$i]%%|*}" == "$1" ]]; then printf '%s' "$i"; return 0; fi
  done
  return 1
}

list_stages() {
  local i id title mark
  for i in "${!STAGES[@]}"; do
    IFS='|' read -r id title _ <<< "${STAGES[$i]}"
    if [[ "$(get "$(done_key "$id")")" == yes ]]; then mark="$GREEN✓$RESET"; else mark=" "; fi
    printf '  %s %2d  %-24s %s\n' "$mark" "$((i + 1))" "$id" "$title"
  done
}

usage() {
  say "scripts/provision.sh            every stage not done yet, in order"
  say "scripts/provision.sh <stage>    one stage, done or not (re-runs are safe)"
  say "scripts/provision.sh --list     the stages, with a tick beside those done"
}

local i id finished=""
case "${1:-}" in
  "")
    banner "Look Together: provision the build (#194)"
    for i in "${!STAGES[@]}"; do
      id="${STAGES[$i]%%|*}"
      if [[ "$(get "$(done_key "$id")")" == yes ]]; then finished="$finished $id"; fi
    done
    if [[ -n "$finished" ]]; then
      say "Done on earlier runs, so we'll skip them:$finished"
      note "Redo one with scripts/provision.sh <stage>."
      pause "Press Enter to go on."
    fi
    for i in "${!STAGES[@]}"; do
      id="${STAGES[$i]%%|*}"
      if [[ "$(get "$(done_key "$id")")" == yes ]]; then continue; fi
      run_stage "$i" skip
    done
    finish
    ;;
  -l|--list) list_stages ;;
  -h|--help) usage ;;
  *)
    if ! i=$(stage_number "$1"); then
      warn "There's no stage called $1."
      list_stages
      exit 1
    fi
    run_stage "$i"
    finish
    ;;
esac
}

run_wizard "$@"; exit
